class Command(BaseCommand):
    help = "Добавляет или обновляет демонстрационный каталог фильмов."

    def handle(self, *args, **kwargs):
        for title, original, year, description, genre, country, director, duration, rating in DATA:
            Movie.objects.update_or_create(
                title=title,
                year=year,
                defaults={
                    "original_title": original,
                    "description": description,
                    "genre": genre,
                    "country": country,
                    "director": director,
                    "duration": duration,
                    "site_rating": rating,
                    "actors": ACTOR_MAP.get(title, ""),
                },
            )

        count = Movie.objects.count()
        self.stdout.write(self.style.SUCCESS(f"Готово: в базе {count} фильмов."))
